      "observed": "The netlist contains no component with value or part 'CH330'. The Connections sheet has USB connectors and series resistors but no USB-UART bridge ICs.",
      "expected": "Spec says 'USB-UART bridges (programming/debug) otter_CH330 ×2'.",
      "evidence": [
        {"source": "spec", "quote": "USB-UART bridges (programming/debug) | Connections | otter_CH330 ×2"},
        {"source": "netlist", "quote": "No component with value 'CH330' or part 'CH330' exists in the netlist."}
      ],
      "impact": "UART-to-USB programming/debug interfaces are nonfunctional; the board cannot be programmed or debugged via UART-to-USB.",
      "confidence": 0.95
    }
